agent_runs.agent_sql:
SELECT DISTINCT ?policyId WHERE {
  ?lp a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/LifeParticipant> ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/LifeParticipant/holding_id> ?hid ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/LifeParticipant/party_id> ?pid ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/LifeParticipant/participant_sk> ?sk .
  ?h a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding> ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding/holding_id> ?hid ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding/policy_id> ?policyId .
}
GROUP BY ?hid ?policyId ?pid
HAVING (COUNT(DISTINCT ?sk) > 1)

SELECT ?partyType ?description
WHERE {
  ?p a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party> ;
     <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party/party_type> ?partyType .
  BIND(?partyType AS ?description)
}
GROUP BY ?partyType ?description
ORDER BY DESC(COUNT(?p))
LIMIT 5

SELECT ?rider_name ?full_name ?role WHERE {
  ?rider a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Rider> ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Rider/rider_name> ?rider_name ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Rider/holding_id> ?holdingId ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Rider/is_deleted> ?riderDeleted .
  FILTER(LCASE(STR(?riderDeleted)) IN ("false", "0", "f", "no", "n"))

  ?coverage a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage> ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/holding_id> ?holdingId ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/party_id> ?partyIdRaw ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/coverage_type> ?role ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/is_deleted> ?covDeleted .
  FILTER(LCASE(STR(?covDeleted)) IN ("false", "0", "f", "no", "n"))

  BIND(CONCAT("PARTY#", ?partyIdRaw) AS ?partyId)

  ?party a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party> ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party/party_id> ?partyId ;
    <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party/full_name> ?full_name .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(?marketValue) AS ?totalMarketValue) ?partyName
WHERE {
  ?holding a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding> ;
           <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding/holding_id> ?holdingId ;
           <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding/holding_status> "Active" ;
           <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding/market_value> ?marketValue .

  ?coverage a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage> ;
            <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/holding_id> ?holdingId ;
            <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/party_id> ?covPartyId .

  BIND(CONCAT("PARTY#", ?covPartyId) AS ?partyIdFull)

  ?party a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party> ;
         <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party/party_id> ?partyIdFull ;
         <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party/full_name> ?partyName .
}
GROUP BY ?partyName
ORDER BY ?partyName

SELECT ?product_name WHERE {
  ?cp a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/CoverageProduct> ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/CoverageProduct/product_name> ?product_name .
}
ORDER BY ?product_name
LIMIT 10

SELECT ?month (SUM(?amount) AS ?totalAmount)
WHERE {
  ?fa a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/FinancialActivity> ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/FinancialActivity/transaction_date> ?date ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/FinancialActivity/transaction_amount> ?amount ;
      <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/FinancialActivity/is_deleted> ?deleted .
  FILTER(LCASE(STR(?deleted)) = "false")
  BIND(SUBSTR(STR(?date),1,7) AS ?month)
  FILTER(SUBSTR(STR(?date),1,4) = "2024")
}
GROUP BY ?month
ORDER BY ?month

SELECT ?partyName ?totalMarketValue (GROUP_CONCAT(DISTINCT ?productName; separator=", ") AS ?investmentProductNames)
WHERE {
  {
    SELECT ?party ?partyName (SUM(?marketValue) AS ?totalMarketValue)
    WHERE {
      ?party a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party> ;
             <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Party/full_name> ?partyName .
      ?coverage a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage> ;
                <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/hasParty> ?party ;
                <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/hasHolding> ?holding .
      ?holding a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding> ;
               <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Holding/market_value> ?marketValue .
    }
    GROUP BY ?party ?partyName
    ORDER BY DESC(?totalMarketValue)
    LIMIT 10
  }
  ?coverage2 a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage> ;
             <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/hasParty> ?party ;
             <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/hasHolding> ?holding2 .
  OPTIONAL {
    ?sub a <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/HoldingSubaccount> ;
         <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/HoldingSubaccount/hasHolding> ?holding2 ;
         <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/HoldingSubaccount/fundname> ?fundname .
  }
  OPTIONAL {
    ?coverage2 <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/Coverage/hasPolicyProduct> ?pp .
    ?pp <http://curated-layer-ontology-20261002-180610/ontology/vkg-ontology_curated_layer-3d1b9153/PolicyProduct/product_name> ?ppName .
  }
  BIND(COALESCE(?fundname, ?ppName, "N/A") AS ?productName)
}
GROUP BY ?partyName ?totalMarketValue
ORDER BY DESC(?totalMarketValue)
